//! Golden vectors from colour-science 0.4.7, generated by
//! `tools/golden/gen_dng.py`.

use std::sync::LazyLock;

use looklab_color::dng::{cct_to_xy_robertson, xy_to_cct_robertson};
use serde::Deserialize;

#[derive(Deserialize)]
struct Golden {
    xy_to_cct: Vectors,
    cct_to_xy: Vectors,
}

#[derive(Deserialize)]
struct Vectors {
    inputs: Vec<Vec<f64>>,
    outputs: Vec<Vec<f64>>,
}

static GOLDEN: LazyLock<Golden> = LazyLock::new(|| {
    serde_json::from_str(include_str!("golden/dng.json")).expect("golden vectors parse")
});

#[test]
fn xy_to_cct_matches_colour_science() {
    assert_eq!(
        GOLDEN.xy_to_cct.inputs.len(),
        GOLDEN.xy_to_cct.outputs.len()
    );
    for (input, expected) in GOLDEN
        .xy_to_cct
        .inputs
        .iter()
        .zip(&GOLDEN.xy_to_cct.outputs)
    {
        let actual = xy_to_cct_robertson(input[0], input[1]);
        let expected = expected[0];
        let tolerance = (expected.abs() * 1.0e-6).max(1.0e-6);
        assert!(
            (actual - expected).abs() <= tolerance,
            "actual {actual:?}, expected {expected:?}"
        );
    }
}

#[test]
fn cct_to_xy_matches_colour_science() {
    assert_eq!(
        GOLDEN.cct_to_xy.inputs.len(),
        GOLDEN.cct_to_xy.outputs.len()
    );
    for (input, expected) in GOLDEN
        .cct_to_xy
        .inputs
        .iter()
        .zip(&GOLDEN.cct_to_xy.outputs)
    {
        let actual = cct_to_xy_robertson(input[0]);
        assert!(
            (actual.0 - expected[0]).abs() <= 1.0e-6 && (actual.1 - expected[1]).abs() <= 1.0e-6,
            "actual {actual:?}, expected {expected:?}"
        );
    }
}
